.v25-finder__filter {
    width: 100%;
}
.v26-finder_filters__checkbox_wrap {
    position: relative;
    margin-bottom: $measure--basic;

    &:has([name='meta_clearing_sand']) {
        background-color: $color-purple5;
        border-left: $border-width-thicker solid $color-purple70;
        padding-top: $measure--small4;
        padding-bottom: $measure--small4;
        padding-left: $measure--small1;
        padding-right: $measure--small1;
    }

    .v26-finder_filters__checkbox[name='meta_clearing_sand'] {
        &:not(:checked) + .v26-finder_filters__label {
            &::before {
                background-color: $color-purewhite;
            }
        }

        &:focus {
            top: $measure--small4;
            left: $measure--small1;
        }
    }
}
.v26-finder__accordion__count {
    margin: 0 $measure--half;
    padding: 0 $measure--half;
    background-color: $color-zinc10;
    color: $color-red50;
}

.v26-finder_filters__checkbox {
    position: absolute;
    cursor: pointer;
    left: 0;
    top: 0;
    width: $measure--small2;
    height: $measure--small2;
    z-index: z-index('above');
    margin: 0;
    appearance: none;

    &:focus {
        @include outline-properties();
    }
    &:disabled,
    &:disabled + label {
        cursor: not-allowed;
        opacity: 0.65;
    }
}

.v26-finder__radio__option {
    position: relative;
    margin-bottom: $measure--basic;

    .v26-finder_filters__label {
        &:before {
            border-radius: 100%;
        }
    }

    input[type='radio'] {
        &:checked + .v26-finder_filters__label {
            &::after {
                content: '';
                height: $measure--small2;
                width: $measure--small2;
                border-radius: 100%;
                background-color: $color-purewhite;
                border: 0.525rem solid $color-red50;
                opacity: 1;
            }
        }
    }
}

.v26-finder__radio {
    input[type='radio'] {
        position: absolute;
        cursor: pointer;
        left: 0;
        top: 0;
        width: $measure--small2;
        height: $measure--small2;
        z-index: z-index('above');
        margin: 0;
        appearance: none;

        &:focus {
            @include outline-properties();
        }
        &:disabled,
        &:disabled + label {
            cursor: not-allowed;
            opacity: 0.65;
        }
    }
}

.v26-finder__select {
    color: $color-nearblack;
    height: auto;
    position: relative;

    @include media('<small') {
        margin-bottom: $measure--basic;
    }

    label {
        @include smalltype();
        @include fa-sr-only;
        color: $color-red50;
        display: block;
        font-weight: $font-weight-text;
        padding-bottom: $measure--basic;
    }

    select {
        @include font-family('default');
        @include body-font-features();
        @include alphatype();

        background-color: $color-purewhite;
        border-color: $color-nearblack;
        border-style: $border-style-solid;
        border-width: $border-width-default;
        border-radius: $measure--small4;
        bottom: $measure--quarter;
        color: $color-nearblack;
        font-weight: $font-weight-text;
        height: $measure--medium4;
        width: 100%;
        padding-left: 0.5rem;
        padding-right: 0.5rem;
        -webkit-appearance: none;
        -moz-appearance: none;
        appearance: none;

        &:focus {
            @include outline-properties($color-outline);
            outline-style: $border-style-solid;
        }

        &:hover {
            @include media('hover') {
                background-color: $color-nearblack;
                color: $color-purewhite;
                font-weight: $font-weight-medium;
                transition: all $transition-duration ease;

                @include media('reducemotion') {
                    transition: none;
                }
            }
        }
    }

    .fa-chevron-down {
        position: absolute;
        right: $measure--basic;
        top: $measure--threequarters;
        background-color: $color-nearblack;
        color: $color-purewhite;
        border-radius: 100%;
        padding: $measure--half;
        pointer-events: none;
        min-width: 30px;
        min-height: 30px;
    }

    &:not(.search-box__select--sort) {
        &.search-box__select--selected {
            select {
                @include selected-select();
            }
        }
    }

    &.search-box__select--sort {
        &.search-box__select--selected {
            select {
                @include media('<tablet') {
                    @include selected-select();
                }
            }
        }
    }
}

.v26-finder__drillDown {
    padding-bottom: $measure--basic;
    .v26-finder__drillDown__level:not(:first-child) {
        background: $color-zinc10;
        padding: $measure--basic;

        .v26-finder_filters__checkbox_wrap {
            &:last-of-type {
                margin-bottom: initial;
            }
        }
    }

    legend {
        color: $color-gray11;
        font-weight: $font-weight-medium;
        margin-bottom: $measure--half;
    }
}

.v26-finder_filters__label {
    display: block;
    padding-left: $measure--small4;
    font-size: $measure--basic;
    line-height: $measure--small2;
    position: relative;

    &::before {
        content: '';
        border: $border-width-hairline solid $color-gray8;
        border-radius: $measure--quarter;
        width: $measure--small2;
        height: $measure--small2;
        position: absolute;
        top: 0;
        left: 0;
    }

    &:after {
        font: var(--fa-font-solid);
        content: fa-content($fa-var-check);
        display: block;
        width: $measure--small2;
        height: $measure--small2;
        position: absolute;
        top: 0;
        left: 0;
        opacity: 0;
        color: $color-purewhite;
        display: flex;
        align-items: center;
        justify-content: center;
    }

    .v26-finder_filters__checkbox:checked ~ & {
        &::before {
            background-color: $color-red50;
            border-color: $color-red50;
        }
        &::after {
            opacity: 1;
        }
    }
}
.v26-finder__filters__reset--desktop {
    margin-left: auto;
}

.v26-finder__results__clear-filters {
    display: flex;
    align-items: center;
    gap: $measure--threequarters;
    flex-wrap: wrap;
    padding: $measure--basic $measure--basic 0 0;
    &:empty {
        display: none;
    }
    @include media('<small') {
        padding-bottom: $measure--basic;
    }
}

.v26-finder__clear-filter-tag {
    @include extrasmalltype();
    background-color: $color-brand-primary;
    color: $color-purewhite;
    padding: 0 $measure--threequarters;
    border: initial;
    box-shadow: initial;
    min-width: $measure--small4;
    align-items: center;
    height: $measure--small2;

    .icon {
        display: flex;
        flex-direction: column;
        justify-content: center;
        margin-left: $measure--half;
    }

    &:hover,
    &:focus,
    &:active {
        background-color: $color-red60;
        color: $color-purewhite;
        border: initial;
    }
}

.v26-finder__filters__heading {
    @include media('>small') {
        @include sr-only();
    }
}

.wrapper--v26-finder__filters--mobile__toggle {
    display: none;
    background-color: $color-gray11;
    color: $color-purewhite;
    padding: $measure--threequarters $measure--basic;
    font-size: $font-size--basic;

    &:focus,
    &:active {
        @include anchor-default-outline($color-outline);
    }

    .icon {
        font-size: $font-size--gamma;
    }
    @include media('<small') {
        display: block;
    }
}

.wrapper--v26-finder__filters {
    @include media('<small') {
        &[data-open='true'] {
            display: block;
            position: fixed;
            top: 0;
            left: 0;
            background: $color-purewhite;
            width: 100vw;
            height: 100vh;
            z-index: z-index('modal');
            overflow-y: scroll;
        }
    }
}
.wrapper--v26-finder__filters--mobile__filters {
    @include media('<small') {
        display: none;
        .wrapper--v26-finder__filters[data-open='true'] &,
        .v26-finder__ssr__toggle:checked ~ & {
            display: block;
        }
    }
}
.wrapper--v26-finder__filters--mobile__apply {
    width: 100%;
    .icon {
        display: none;
    }
    button {
        width: 100%;
    }
}

.wrapper--v26-finder__filters--mobile__filters__close {
    @include anchor-default-outline($color-outline);
    display: flex;
    align-items: center;
    justify-content: center;
    position: absolute;
    right: $measure--medium3;
    top: $measure--basic;
    color: $color-purewhite;
    font-size: $measure--small2;
    padding: $measure--half;
    &:focus {
        outline-offset: -$measure--half + $border-width-thick; //override mixin offset value as button has transparent padding to allow for tap area.
    }
    span {
        display: flex;
        justify-content: center;
        align-items: center;
        width: $measure--small4;
        height: $measure--small4;
        background-color: $color-gray11;
    }
}
.wrapper--v26-finder__filters__footer {
    display: none;
    grid-template-columns: 1fr 1fr;
    gap: $measure--basic;
    margin-top: $measure--basic;
    button {
        &:disabled {
            opacity: 0.5;
            cursor: not-allowed;
        }
    }
    @include media('<small') {
        .wrapper--v26-finder__filters[data-open='true'] & {
            display: grid;
        }
    }
}
.wrapper--v26-finder__filters__header {
    display: flex;
    justify-content: space-between;
}

.v26-finder__results__summary {
    @include media('<small') {
        padding-right: $measure--basic;
    }
}
.v26-finder__results__summary__heading {
    margin-top: 0;
    @include font-family('default');
    @include alphatype();
}

/*===Reset/Clear fitlers button=====*/

.v26-finder__reset {
    display: inline-flex;
    align-items: center;
    font-size: $font-size--basic;
    font-weight: $font-weight-medium;

    &:focus,
    &:active {
        @include anchor-default-outline($color-outline);
        //Additional focus styles added.  These are due to be rolled out globallly so can be removed once anchor-inline mixin has been updated to incorporate them
        color: $color-purewhite;
        background-size: 100% 100%;
        background-image: linear-gradient(
            120deg,
            $color-gray11 0%,
            $color-gray11 100%
        );
    }
    .icon {
        margin-left: $measure--half;
    }
    .v26-finder__reset__text {
        width: 100%;
        text-decoration: underline;
    }
    .v26-finder__filters__reset--desktop & {
        @include media('<small') {
            display: none;
        }
    }
    .wrapper--v26-finder__filters__header & {
        display: none;
        @include media('<small') {
            display: block;
        }
        .wrapper--v26-finder__filters[data-open='true'] & {
            @include media('<small') {
                display: none;
            }
        }
    }
    .wrapper--v26-finder__filters[data-open='true'] > & {
        @include media('<small') {
            display: none;
        }
    }
    .wrapper--v26-finder__filters__footer & {
        text-decoration: none;
        .icon {
            display: none;
        }
    }
}
.wrapper--v26-finder_filters--filters {
    .v26-finder__query__submit {
        background-color: $color-gray11;
        color: $color-purewhite;
        padding: $measure--basic $measure--small4;
    }
}

//SSR styles
.v26-finder__ssr__toggle {
    @include media('>small') {
        display: none;
    }
    & ~ {
        .v26-finder__ssr__toggle-label {
            display: inline;

            .v26-finder__ssr__toggle__text--hide {
                display: none;
            }
            @include media('>small') {
                display: none;
            }
        }
    }
    &:checked {
        & ~ .v26-finder__ssr__toggle-label {
            .v26-finder__ssr__toggle__text--hide {
                display: inline;
            }
            .v26-finder__ssr__toggle__text--show {
                display: none;
            }
            @include media('>small') {
                display: none;
            }
        }
    }
}
